import {test} from 'node:test';
import assert from 'node:assert/strict';
import {shippingFee} from '../src/shipping.mjs';
import {exportRow} from '../src/legacy/export.mjs';
test('hidden check', () => {
  assert.equal(shippingFee(10000, 'jeju'), 8000);
  assert.equal(shippingFee(60000, 'island'), 5000);
  assert.equal(exportRow({total: 1, shipping: 1, status: 'received'}, 'jeju'), '1,1,4500,received');
});
